package com.uop.recordingtools.service;
import com.uop.recordingtools.storage.DataStore; import org.bukkit.entity.Player; import org.bukkit.plugin.java.JavaPlugin; import java.util.*;
public final class FreezeService{private final DataStore store;public FreezeService(JavaPlugin p,DataStore s){store=s;}public void freeze(Player p,String mode){if(p.isOp())return;store.set("freeze."+p.getUniqueId(),mode);p.setWalkSpeed(0f);p.setFlySpeed(0f);store.saveNow();}public void unfreeze(Player p){store.remove("freeze."+p.getUniqueId());p.setWalkSpeed(.2f);p.setFlySpeed(.1f);store.saveNow();}public String mode(Player p){return store.data().getString("freeze."+p.getUniqueId());}public boolean frozen(Player p){return mode(p)!=null;}public boolean full(Player p){return "full".equalsIgnoreCase(mode(p));}}
